private fun uploadManualMedia(file: File, mimeType:String): Observable<UploadImageMatrixResp>{
        val body =  file.asRequestBody(mimeType.toMediaTypeOrNull())
        return matrixAPI.uploadImageToMatirxServer(body)
            .subscribeOn(Schedulers.io())
            .observeOn(AndroidSchedulers.mainThread())
    }
